#!/usr/bin/env python3
import sys, json, re, zipfile, shutil, os
import xml.etree.ElementTree as ET

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
WNS = '{%s}' % W
ET.register_namespace('w', W)
# register other common namespaces to preserve prefixes
NS = {
 'wpc':'http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas',
 'mo':'http://schemas.microsoft.com/office/mac/office/2008/main',
 'mc':'http://schemas.openxmlformats.org/markup-compatibility/2006',
 'mv':'urn:schemas-microsoft-com:mac:vml',
 'o':'urn:schemas-microsoft-com:office:office',
 'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
 'm':'http://schemas.openxmlformats.org/officeDocument/2006/math',
 'v':'urn:schemas-microsoft-com:vml',
 'wp14':'http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing',
 'wp':'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing',
 'w10':'urn:schemas-microsoft-com:office:word',
 'w':W,
 'w14':'http://schemas.microsoft.com/office/word/2010/wordml',
 'wpg':'http://schemas.microsoft.com/office/word/2010/wordprocessingGroup',
 'wpi':'http://schemas.microsoft.com/office/word/2010/wordprocessingInk',
 'wne':'http://schemas.microsoft.com/office/word/2006/wordml',
 'wps':'http://schemas.microsoft.com/office/word/2010/wordprocessingShape',
}
for k,v in NS.items():
    ET.register_namespace(k, v)

INP_DOCX = 'inputs/offer_letter_template.docx'
INP_JSON = 'inputs/employee_data.json'
OUT_DOCX = 'output/offer_letter_filled.docx'

PH = re.compile(r'\{\{([A-Z_][A-Z0-9_]*)\}\}')
COND = re.compile(r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}', re.S)

def fail(msg):
    sys.stderr.write('ERROR: ' + msg + '\n')
    sys.exit(2)

def load_data():
    with open(INP_JSON, encoding='utf-8') as f:
        return json.load(f)

def apply_conditional(text, data, missing):
    # IF_RELOCATION governed solely by RELOCATION_PACKAGE
    def repl(m):
        if 'RELOCATION_PACKAGE' not in data:
            missing.add('RELOCATION_PACKAGE')
            return ''  # placeholder; will fail later
        keep = (data['RELOCATION_PACKAGE'] == 'Yes')
        return m.group(1) if keep else ''
    return COND.sub(repl, text)

def apply_fields(text, data, missing):
    def repl(m):
        name = m.group(1)
        if name in ('IF_RELOCATION','END_IF_RELOCATION'):
            # leftover (shouldn't happen) -> leave to detect
            return m.group(0)
        if name not in data:
            missing.add(name)
            return m.group(0)
        return str(data[name])
    return PH.sub(repl, text)

def get_t_nodes(p):
    return [t for t in p.iter(WNS+'t')]

def para_has_cond(p):
    full = ''.join((t.text or '') for t in get_t_nodes(p))
    return ('IF_RELOCATION' in full) or ('{{' in full)

def process_paragraph(p, data, missing):
    tnodes = get_t_nodes(p)
    if not tnodes:
        return
    full = ''.join((t.text or '') for t in tnodes)
    if '{{' not in full:
        return
    new = apply_conditional(full, data, missing)
    new = apply_fields(new, data, missing)
    if new == full:
        return
    # Put all text in first t node, clear the rest
    first = tnodes[0]
    first.text = new
    # preserve space on first node
    first.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    for t in tnodes[1:]:
        t.text = ''

def process_part(xml_bytes, data, missing):
    root = ET.fromstring(xml_bytes)
    for p in root.iter(WNS+'p'):
        process_paragraph(p, data, missing)
    return ET.tostring(root, encoding='UTF-8', xml_declaration=True)

def main():
    data = load_data()
    zin = zipfile.ZipFile(INP_DOCX)
    names = zin.namelist()
    parts = [n for n in names if n.startswith('word/') and
             (n.endswith('document.xml') or
              re.match(r'word/header\d+\.xml$', n) or
              re.match(r'word/footer\d+\.xml$', n))]
    missing = set()
    outbuf = {}
    for n in parts:
        outbuf[n] = process_part(zin.read(n), data, missing)

    # Validate: any remaining {{...}} tokens anywhere in processed parts?
    leftover = set()
    for n, b in outbuf.items():
        s = b.decode('utf-8')
        txt = re.sub(r'<[^>]+>','', s)
        for m in PH.finditer(txt):
            leftover.add(m.group(1))
        if 'IF_RELOCATION' in txt or 'END_IF_RELOCATION' in txt:
            leftover.add('IF_RELOCATION')

    problems = set(missing) | leftover
    if problems:
        zin.close()
        fail('Missing required field(s): ' + ', '.join(sorted(problems)))

    os.makedirs(os.path.dirname(OUT_DOCX), exist_ok=True)
    with zipfile.ZipFile(OUT_DOCX, 'w', zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data_bytes = outbuf.get(item.filename)
            if data_bytes is None:
                data_bytes = zin.read(item.filename)
            zout.writestr(item, data_bytes)
    zin.close()
    print('Wrote', OUT_DOCX)

if __name__ == '__main__':
    main()
